 try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();ensureAmbient();const note={tap:[480,.045],open:[620,.09],build:[330,.15],bus:[740,.11],tool:[540,.055],alert:[680,.13],save:[720,.16],zoom:[390,.055],error:[170,.16]}[type]||[480,.05],osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type=type==='build'?'triangle':'sine';osc.frequency.setValueAtTime(note[0],now);osc.frequency.exponentialRampToValueAtTime(note[0]*.82,now+note[1]);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.055,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+note[1]);osc.connect(gain).connect(audioContext.destination);osc.start(now);osc.stop(now+note[1]+.01)}catch{}
