let ambientTimer=null,ambientChord=0;function ambientMusic(){if(!soundEnabled||!audioContext||document.hidden)return;const sequence=[[220,277,330],[196,246,294],[174,220,261],[196,261,330]],notes=sequence[ambientChord++%sequence.length],now=audioContext.currentTime;for(const [i,note] of notes.entries()){const tone=audioContext.createOscillator(),filter=audioContext.createBiquadFilter(),env=audioContext.createGain();tone.type=i?'sine':'triangle';tone.frequency.value=note;filter.type='lowpass';filter.frequency.value=900;env.gain.setValueAtTime(.0001,now);env.gain.linearRampToValueAtTime(.008,now+.8);env.gain.setValueAtTime(.008,now+3.2);env.gain.exponentialRampToValueAtTime(.0001,now+6);tone.connect(filter).connect(env).connect(audioContext.destination);tone.start(now);tone.stop(now+6.1)}}function ensureAmbient(){if(ambientTimer||!soundEnabled)return;ambientMusic();ambientTimer=setInterval(ambientMusic,7200)}
