function catalogCategory(button){const tool=button.dataset.tool,model=button.dataset.model||'',transitTools=['busGarage','busStop','taxiStop','port','airport','metroStation','railStation','metroLink','railLink'];const healthModels=['clinic','medicalCenter','generalHospital'];const educationModels=['kindergarten','primarySchool','secondarySchool','university'];const communityModels=['socialShelter','elderCare','cemetery','crematorium','urbanPark'];const safetyModels=['policePost','policeStation','policeHQ','firePost','fireStationPlus','fireCommand'];const environmentModels=['wasteYard','wasteDepot','wasteComplex'];const networkModels=['tvHeadend','wifiHub'];if(transitTools.includes(tool)||model==='taxiYard'||model==='parkingGarage')return'transport';if(['powerLine','waterPipe','sewerLine','drainLine','gasLine','telecomLine','powerPlant','waterPlant','gasPlant','wastewaterPlant'].includes(tool)||networkModels.includes(model))return'networks';if(tool.startsWith('zoneHome')||tool.startsWith('zoneShop')||tool.startsWith('zoneFactory')||tool.startsWith('zoneOffice')||tool==='zoneClear')return'zoning';if(['home','shop','hotel'].includes(tool))return'housing';if(tool==='factory')return'industry';if(tool==='road'||tool==='bridge'||tool==='inspect')return'terrain';if(healthModels.includes(model))return'health';if(educationModels.includes(model))return'education';if(communityModels.includes(model))return'community';if(safetyModels.includes(model)||tool==='fireStation')return'safety';if(environmentModels.includes(model)||['wasteContainer','landfill','recyclingPlant'].includes(tool))return'environment';return'community'}
