document.querySelectorAll('.game-dock [data-popup]:not([data-popup="traffic"])').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.popup==='alerts')renderAlertsPanel();const titles={alerts:'Qu\u00e9 est\u00e1 pasando',build:'Construir',city:'Partida y ciudad',supply:'Econom\u00eda y suministros',projects:'Obras y contratos',events:'Registro de acontecimientos',changes:'Cambios de versi\u00f3n'};openPopup(titles[button.dataset.popup],popupGroups[button.dataset.popup]||[]);decorateReferencePopup(button.dataset.popup,popupBody,S,{ui,alerts:cityAlerts,version:releaseData?.currentVersion||document.querySelector('meta[name="ciudad-viva-version"]')?.content||'0.227',phases:releaseData?.roadmapPhases?.length||34})}));
