 const buildings=state.buildings||[],homes=buildings.filter(b=>b.kind==='home'),businesses=buildings.filter(b=>['shop','factory','office'].includes(b.kind)&&b.business?.status!=='cerrado'),schools=buildings.filter(b=>b.kind==='school'||b.serviceModel==='university'),serviceSites=buildings.filter(b=>b.kind==='civic'||b.kind==='school'),environment=state.environmentReport?.tiles||[];
 const residents=near(homes,6,b=>Math.max(0,Number(b.occupants)||0)),localJobs=near(businesses,6,b=>Math.max(0,Number(b.business?.jobSlots||b.jobSlots||0))),education=near(schools,7,b=>b.serviceModel==='university'?18:7),services=near(serviceSites,6,b=>b.kind==='school'?7:b.serviceModel==='urbanPark'?4:5),exposure=near(environment,1,t=>(Number(t.air)||0)+(Number(t.noise)||0)*.7+(Number(t.heat)||0)*.4),cityServices=Math.max(0,Math.min(100,Number(state.services)||0));
