 if(zone.kind==='home')score+=cityServices*.15+Math.min(18,services*.8)+Math.min(20,localJobs*.18)+Math.min(18,residents*.12)-Math.min(20,exposure*.12);
 else if(zone.kind==='shop')score+=Math.min(48,residents*.42)+Math.min(18,localJobs*.08)-Math.min(18,near(businesses.filter(b=>b.kind==='shop'),4,()=>5));
 else if(zone.kind==='office')score+=Math.min(32,education*.65)+Math.min(28,residents*.2)+Math.min(24,(demand.office.unplacedGraduates||0)*.75);
