function automaticContractor(kind='road'){
 const candidates=offers.map(name=>({name,c:S?.contractors?.[name]})).filter(x=>x.c).map(({name,c})=>{
  const active=(S.projects||[]).filter(p=>p.contractor===name&&p.status!=='pausada'),repairs=(S.contractGuarantees||[]).filter(g=>g.contractor===name&&g.status==='reparacion'),recovery=(S.recoveryContracts||[]).filter(p=>p.contractor===name&&p.status==='en obra'),otherWorks=['heritageWorks','adaptiveReuseWorks','urbanRenewalWorks','environmentalWorks'].flatMap(k=>S[k]||[]).filter(w=>w.contractor===name&&w.status==='en obra'),industrial=(S.buildings||[]).filter(b=>b.industrialRecovery?.status==='en obra'&&b.industrialRecovery.contractor===name),workers=active.reduce((n,p)=>n+(p.workersAssigned||0),0)+repairs.reduce((n,g)=>n+(g.workersAssigned||3),0)+recovery.reduce((n,p)=>n+(p.workers||4),0)+otherWorks.reduce((n,w)=>n+(w.workers||4),0)+industrial.reduce((n,b)=>n+(b.industrialRecovery.workersAssigned||0),0)+(S.supply?.orders||[]).filter(o=>o.contractor===name&&o.status==='descargando').reduce((n,o)=>n+(o.unloadWorkers||0),0),slots=(c.capacity||0)-active.length-repairs.length-recovery.length-otherWorks.length-industrial.length;
  return{name,c,freeWorkers:(c.workers||0)-workers,slots}
 }).filter(x=>x.slots>0&&x.freeWorkers>=(laborNeeds[kind]||4));
 return candidates.sort((a,b)=>a.c.price-b.c.price||a.c.days-b.c.days||b.c.quality-a.c.quality)[0]?.name||null
}
function isInstantPublicService(kind,model){return kind==='fireStation'||(kind==='civic'&&['clinic','medicalCenter','generalHospital','policePost','policeStation','policeHQ','parkingGarage'].includes(model||'clinic'))}
function placeQuick(kind,x,y,busLineId=null,serviceModel=null,industryType=null,rescueId=null,roadType=toolRoadType){
 const start=async()=>{
  if(!S||!kind)return;
  if(kind==='road'){await send('placeRoad',{x,y,roadType:ROAD_TYPES[roadType]?roadType:'local'});return}
  if(!rescueId&&isInstantPublicService(kind,serviceModel)){await send('place',{kind,x,y,serviceModel});return}
  // Both modes place manually chosen buildings instantly without reserving crews.
  // Rescue contracts are still staged and require a real available contractor.
  const contractor=automaticContractor(kind)||(rescueId?null:'Sur Obras');
  if(!contractor){showToast('No hay una cuadrilla compatible disponible para rescatar la obra.');return}
  const payload=rescueId?{id:rescueId,contractor}:{kind,x,y,contractor,busLineId,serviceModel,industryType};
  await send(rescueId?'rescue':'place',payload);
 };
 placementQueue=placementQueue.then(start,start);return placementQueue;
}
