async function poll(generation=modeGeneration){
 if(!gameMode||generation!==modeGeneration)return;
 let retryDelay=gameMode==='online'?0:500;
 try{
  const syncPath=gameMode==='online'?'/api/sync?revision='+encodeURIComponent(S?.stateRevision??0):'/api/state';
  const next=await api(syncPath);
  if(generation!==modeGeneration)return;
  if(next.heartbeat){
   S={...S,online:next.online,onlinePlayers:next.onlinePlayers||S.onlinePlayers,paused:next.paused,speed:next.speed,day:next.day,timeOfDayMinutes:next.timeOfDayMinutes,stateRevision:next.stateRevision,...(Number.isFinite(Number(next.money))?{money:Number(next.money)}:{})};
   if(gameMode==='online')renderOnlineHud();
   if(Number.isFinite(Number(next.money))){ui.money.textContent='$ '+nfmt(S.money);const net=(S.grossMonthlyIncome??S.monthlyIncome)-(S.effectiveMonthlyExpenses??S.monthlyExpenses);ui.budgetFlow.textContent=`${net>=0?'▲ +':'▼ -'} $${nfmt(Math.abs(net))}/mes`;const reserved=(S.projects||[]).filter(p=>!p.privatePaid).reduce((n,p)=>n+Math.max(0,(p.cost||0)-(p.paid||0)),0),balances=ui.treasuryPopover.querySelectorAll('.treasury-balances>div>b');if(balances[0])balances[0].textContent=`$ ${nfmt(S.money)}`;if(balances[1])balances[1].textContent=`$ ${nfmt(Math.max(0,S.money-reserved))}`;if(balances[2])balances[2].textContent=`$ ${nfmt(reserved)}`}
   if(gameMode==='online')ui.playersLabel.textContent='GOBIERNO COMPARTIDO · '+S.online+' CONECTADO'+(S.online===1?'':'S');
   const minutes=Number(next.timeOfDayMinutes??360);
   ui.mapTime.textContent=`${isNight(minutes)?'☾':'☀'} ${formatGameTime(minutes)}`;
   ui.mapTime.title=`${trafficWindowLabel(trafficWindowAt(minutes))} · ${formatGameTime(minutes)}`;
   ui.mapTime.dataset.night=String(isNight(minutes));
   disconnectToast=false;
  }else{
   const changed=!S||next.stateRevision!==S.stateRevision;
   S=changed?next:{...S,...next};
   disconnectToast=false;
   if(changed){renderUI();draw()}
   else{
    ui.money.textContent='$ '+nfmt(next.money);
    const net=(next.grossMonthlyIncome??next.monthlyIncome)-(next.effectiveMonthlyExpenses??next.monthlyExpenses);
    ui.budgetFlow.textContent=`${net>=0?'+':'-'} $${nfmt(Math.abs(net))}/mes`;
    const minutes=Number(next.timeOfDayMinutes??360);
    ui.mapTime.textContent=`${isNight(minutes)?'☾':'☀'} ${formatGameTime(minutes)}`;
    ui.mapTime.title=`${trafficWindowLabel(trafficWindowAt(minutes))} · ${formatGameTime(minutes)}`;
    ui.mapTime.dataset.night=String(isNight(minutes));
    if(gameMode==='online')ui.playersLabel.textContent='GOBIERNO COMPARTIDO · '+S.online+' CONECTADO'+(S.online===1?'':'S');
    if(S.projects?.length){
     const cards=ui.projects.querySelectorAll('.project');
     S.projects.forEach((p,i)=>{
      const pct=Math.floor(visualProjectProgress(p,minutes)*100),label=cards[i]?.querySelector('.project-top span'),bar=cards[i]?.querySelector('.progress i');
      if(label)label.textContent=`${pct}%`;
      if(bar)bar.style.width=`${pct}%`;
     });
     draw();
    }
    if(trafficOverlay){
     const clock=document.getElementById('trafficClock'),windowLabel=document.getElementById('trafficWindow');
     if(clock)clock.textContent=`${isNight(minutes)?'☾':'☀'} ${formatGameTime(minutes)}`;
     if(windowLabel)windowLabel.textContent=trafficWindowLabel(trafficWindowAt(minutes));
     document.querySelectorAll('.traffic-window').forEach(row=>row.classList.toggle('current',row.dataset.window===trafficWindowAt(minutes)));
    }
   }
  }
  if(gameMode==='online')ui.netLabel.textContent=S.isHost?(rtcHost?'Anfitrión · WebRTC y Cloudflare':'Anfitrión · sala compartida'):(rtcSession?.active?`WebRTC directo · ${S.online} conectados`:`Invitado · sala LAN/Internet · ${S.online} conectados`);
 }catch(e){
  if(generation!==modeGeneration)return;
  retryDelay=1000;ui.netLabel.textContent='Sala desconectada';
  if(!disconnectToast){showToast('Se perdió la conexión con la sala. Reintentando…');disconnectToast=true}
 }
 setTimeout(()=>poll(generation),retryDelay);
}
