const themeToggle=document.getElementById('themeToggle'),modeThemeToggle=document.getElementById('modeThemeToggle');function applyTheme(theme){document.body.dataset.theme=theme;for(const toggle of [themeToggle,modeThemeToggle]){const title=theme==='dark'?'Usar modo claro':'Usar modo oscuro';toggle.title=title;toggle.setAttribute('aria-label',title);if(toggle===modeThemeToggle)toggle.textContent=theme==='dark'?String.fromCodePoint(0x2600):String.fromCodePoint(0x263E)}localStorage.setItem('cv-theme',theme)}applyTheme(localStorage.getItem('cv-theme')||'light');for(const toggle of [themeToggle,modeThemeToggle])toggle.addEventListener('click',()=>applyTheme(document.body.dataset.theme==='dark'?'light':'dark'));
